"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76735"],{81622(e){e.exports=JSON.parse('{"id":"FIN-1288","slug":"acquirer","term":"Acquirer","also_known_as":[],"difficulty":"Advanced","definition":"In card payments, an acquirer is the bank or financial institution that enables a merchant to accept card payments, processing transactions on the merchant\'s behalf and depositing the funds into its account.","explanation":["The card payment system has two sides. The issuer is the bank that gives the card to the customer. The acquirer, also called the acquiring bank or merchant acquirer, works with the merchant.","The acquirer signs up merchants, provides or arranges card terminals and online payment services, submits transactions to the card networks for authorisation and settlement, and credits merchants with the money from card sales, minus fees. It also bears some risk, for example if a merchant goes out of business and owes refunds to customers.","For example, a clothing shop opens a merchant account with an acquiring bank. Each time a customer pays by card, the acquirer processes the payment and later pays the shop, deducting fees that include the interchange fee paid to the card issuer.","Many modern payment companies act as acquirers or partner with them to offer simple card acceptance to small businesses. The word acquirer also has a different meaning in mergers and acquisitions, where it refers to a company that buys another company."],"note":"","total":1500,"prev":{"slug":"accumulated-depreciation","term":"Accumulated Depreciation"},"next":{"slug":"acquisition","term":"Acquisition"}}')}}]);